        children: "public final class CaseAccessPolicy {\n\n    public AuthorizationDecision canRead(\n            AuthenticatedPrincipal actor,\n            CaseRecord caseRecord\n    ) {\n        if (!sameTenant(actor, caseRecord)) {\n            return AuthorizationDecision.deny(\"tenant_mismatch\");\n        }\n\n        if (actor.hasPermission(\"case.read.all\")) {\n            return AuthorizationDecision.allow(\"has_case_read_all\");\n        }\n\n        if (actor.hasPermission(\"case.read.assigned\")\n                && actor.subject().equals(caseRecord.assignedUserId())) {\n            return AuthorizationDecision.allow(\"assigned_user\");\n        }\n\n        if (actor.hasPermission(\"case.read.own\")\n                && actor.subject().equals(caseRecord.createdBy())) {\n            return AuthorizationDecision.allow(\"case_creator\");\n        }\n\n        return AuthorizationDecision.deny(\"no_matching_case_read_rule\");\n    }\n\n    public AuthorizationDecision canApprove(\n            AuthenticatedPrincipal actor,\n            CaseRecord caseRecord\n    ) {\n        if (!sameTenant(actor, caseRecord)) {\n            return AuthorizationDecision.deny(\"tenant_mismatch\");\n        }\n\n        if (!actor.hasPermission(\"case.approve\")) {\n            return AuthorizationDecision.deny(\"missing_case_approve_permission\");\n        }\n\n        if (!\"SUBMITTED\".equals(caseRecord.status())) {\n            return AuthorizationDecision.deny(\"case_not_submitted\");\n        }\n\n        if (actor.subject().equals(caseRecord.createdBy())) {\n            return AuthorizationDecision.deny(\"maker_checker_violation\");\n        }\n\n        if (actor.approvalLevel() < caseRecord.riskLevel()) {\n            return AuthorizationDecision.deny(\"approval_level_too_low\");\n        }\n\n        if (!actor.allowedRegions().contains(caseRecord.region())) {\n            return AuthorizationDecision.deny(\"region_not_allowed\");\n        }\n\n        return Authori