        children: "public final class WorkflowTaskAuthorizationPolicy {\n\n    public AuthorizationDecision canReadTask(\n            SecurityActor actor,\n            WorkflowTaskRef task,\n            BusinessObjectRef businessObject\n    ) {\n        if (!actor.tenantContext().canAccessTenant(task.tenantId())) {\n            return AuthorizationDecision.deny(\"task_tenant_not_allowed\");\n        }\n\n        if (!actor.hasPermission(\"workflow.task.read\")) {\n            return AuthorizationDecision.deny(\"missing_workflow_task_read\");\n        }\n\n        if (isAssignedToActor(actor, task)) {\n            return AuthorizationDecision.allow(\"task_assigned_to_actor\");\n        }\n\n        if (isCandidateActor(actor, task)) {\n            return AuthorizationDecision.allow(\"task_candidate_actor\");\n        }\n\n        if (actor.hasPermission(\"workflow.task.read.all\")) {\n            return AuthorizationDecision.allow(\"task_read_all\");\n        }\n\n        return AuthorizationDecision.deny(\"not_task_assignee_or_candidate\");\n    }\n\n    public AuthorizationDecision canCompleteTask(\n            SecurityActor actor,\n            WorkflowTaskRef task,\n            BusinessObjectRef businessObject\n    ) {\n        if (!task.active()) {\n            return AuthorizationDecision.deny(\"task_not_active\");\n        }\n\n        if (!actor.tenantContext().canAccessTenant(task.tenantId())) {\n            return AuthorizationDecision.deny(\"task_tenant_not_allowed\");\n        }\n\n        if (!actor.hasPermission(\"workflow.task.complete\")) {\n            return AuthorizationDecision.deny(\"missing_workflow_task_complete\");\n        }\n\n        if (isAssignedToActor(actor, task)) {\n            return AuthorizationDecision.allow(\"task_complete_assignee\");\n        }\n\n        if (task.assignee() == null && isCandidateActor(actor, task)) {\n            return AuthorizationDecision.allow(\"task_complete_candidate\");\n        }\n\n        if (actor.ha